import sys
src, dst = sys.argv[1], sys.argv[2]
t = open(src, encoding='utf-8').read()
def R(old, new, cnt=1):
    global t
    n = t.count(old)
    if n != cnt: raise SystemExit(f'COUNT {n} != {cnt}: {old[:80]}')
    t = t.replace(old, new)

# 개고 안내
i0 = t.index('> **개고 안내(v0.7'); i1 = t.index('\n', i0)
t = t[:i0] + "> **개고 안내(v0.8, 2026.11.24. 기준, 제출 전 삭제)** v0.7에서 미확인으로 남긴 자료를 원문으로 검증하여 반영하였다. 경찰청 「디지털 증거의 처리 등에 관한 규칙」(경찰청훈령 제1178호)을 제5장 비교에 추가하였고, 「중대범죄수사청 조직 및 운영에 관한 법률」과 그 시행령에 따라 외환의 죄·군사기밀보호법 위반의 수사 주체와 통보·이첩 구조를 반영하였다. 위험범론과 법조경합론에 관한 국내 문헌 5편을 RISS 서지와 초록으로 확인하여 제1장·제3장·제4장의 논증을 보강하였고, 부산 사건 항소심 선고일과 논문 서지의 면수를 보완하였다. 개정 형법의 입법자료(심사보고서·회의록)는 국회 사이트에 접속할 수 없어 확인하지 못하였다." + t[i1:]

